import { Component, EventEmitter, Input } from '@angular/core';

@Component({
  selector: 'app-emp-details',
  templateUrl: './emp-details.component.html',
  styleUrls: ['./emp-details.component.css']
})
export class EmpDetailsComponent {
  @Input() emp_Name: string | undefined=""; 

  empName : string | undefined = this.emp_Name?.toUpperCase();

  @output() event = new EventEmitter();

  sendData(){
    this.event.emit(this.empName)
  }
}
<div style="background-color: brown;">
    <h3 style="color: yellow;">Employee Details are here ...</h3>
    <h3 style="color: yellow;">Employee Name : {{ emp_Name }}</h3>
    <br />
    <button>Send Data from Child to Parent</button>
</div>
